{
  "name": "Professor Nihil: Nihiltheistic Research Engine",
  "description": "A sophisticated philosophical research system for the Nihiltheistic framework (Collapse, Awakening, Integration). Features AI-powered densification, note analysis, and recursive synthesis."
}

export type Phase = 'collapse' | 'awakening' | 'integration' | 'synthesis';

export interface NihiltheisticScore {
  existentialDread: number; // 0-10
  transcendentalYearning: number; // 0-10
  absurdPerspective: number; // 0-10
  voidResonance: number; // 0-10
}

export interface Note {
  id: string;
  title: string;
  content: string;
  phase: Phase;
  scores: NihiltheisticScore;
  tags: string[];
  thinker?: string;
  createdAt: string;
  updatedAt: string;
  aiAnalysis?: string;
}

export interface Concept {
  id: string;
  name: string;
  category: string;
  phase: Phase;
  x: number;
  y: number;
  connections: string[];
}

export interface ResearchQuery {
  id: string;
  prompt: string;
  response: string;
  model: string;
  timestamp: string;
  isDeepResearch: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { NihiltheisticScore, Phase } from "../types";

const getAI = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key not found");
  return new GoogleGenAI({ apiKey });
};

export const analyzeNoteWithGemini = async (
  content: string
): Promise<{ scores: NihiltheisticScore; phase: Phase; analysis: string; tags: string[] }> => {
  const ai = getAI();
  const model = "gemini-3-flash-preview";

  const prompt = `
    Analyze the following philosophical text through the lens of the Nihiltheistic framework (Collapse, Awakening, Integration).

    Determine the following:
    1. Scores (0-10) for: Existential Dread, Transcendental Yearning, Absurd Perspective, Void Resonance.
    2. The primary Phase (collapse, awakening, integration, synthesis).
    3. Suggested tags (max 5).
    4. A brief, clinical, dense philosophical analysis (max 100 words).

    Text:
    "${content}"
  `;

  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          scores: {
            type: Type.OBJECT,
            properties: {
              existentialDread: { type: Type.NUMBER },
              transcendentalYearning: { type: Type.NUMBER },
              absurdPerspective: { type: Type.NUMBER },
              voidResonance: { type: Type.NUMBER },
            },
            required: ["existentialDread", "transcendentalYearning", "absurdPerspective", "voidResonance"],
          },
          phase: { type: Type.STRING, enum: ["collapse", "awakening", "integration", "synthesis"] },
          tags: { type: Type.ARRAY, items: { type: Type.STRING } },
          analysis: { type: Type.STRING },
        },
        required: ["scores", "phase", "tags", "analysis"],
      },
    },
  });

  const json = JSON.parse(response.text || "{}");
  return json;
};

export const deepResearch = async (query: string): Promise<string> => {
  const ai = getAI();
  const model = "gemini-3-pro-preview"; // Using Pro for thinking

  const systemInstruction = `
    You are Professor Nihil, the Journal314 Intensive Iterative Densification Engine.
    Your mission is EVIDENCE-FIRST, PUBLICATION-GRADE, ANTI-CONSOLATORY analysis.
    You do not provide self-help. You analyze through the Nihiltheistic framework.

    Framework:
    - Collapse: Confrontation with meaninglessness.
    - Awakening: Recognition of the void as generative.
    - Integration: Provisional meaning creation.

    Use Thinking Mode to recursively densify the query.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: query,
    config: {
      systemInstruction,
      thinkingConfig: { thinkingBudget: 16000 }, // High budget for deep thought
    },
  });

  return response.text || "Analysis failed.";
};

export const quickSynthesize = async (notes: string[]): Promise<string> => {
    const ai = getAI();
    // Using flash for quick multiple-doc synthesis if needed, or pro without thinking if speed/cost balanced
    // But user asked to use Pro for complex tasks. Synthesis is complex.
    // Let's use Flash Lite for speed if the user wants quick UI updates, but here we want quality.
    // We'll use gemini-3-flash-preview as a balance for "quick" synthesis in UI.
    const model = "gemini-3-flash-preview";

    const prompt = `
      Synthesize the following research notes into a coherent paragraph identifying emerging patterns in the Nihiltheistic framework.
      Notes:
      ${notes.join("\n---\n")}
    `;

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
    });

    return response.text || "Synthesis failed.";
}

