import React, { useState, useEffect } from 'react';
import { Save, Sparkles, Tag, Clock, Activity } from 'lucide-react';
import { Note, NihiltheisticScore } from '../types';
import { analyzeNoteWithGemini } from '../services/geminiService';

interface NoteEditorProps {
  notes: Note[];
  setNotes: React.Dispatch<React.SetStateAction<Note[]>>;
}

export const NoteEditor: React.FC<NoteEditorProps> = ({ notes, setNotes }) => {
  const [selectedNoteId, setSelectedNoteId] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  // Create new note if none selected or create requested
  const handleCreateNote = () => {
    const newNote: Note = {
      id: crypto.randomUUID(),
      title: 'Untitled Entry',
      content: '',
      phase: 'collapse',
      scores: { existentialDread: 0, transcendentalYearning: 0, absurdPerspective: 0, voidResonance: 0 },
      tags: [],
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };
    setNotes([newNote, ...notes]);
    setSelectedNoteId(newNote.id);
  };

  const activeNote = notes.find(n => n.id === selectedNoteId);

  const updateActiveNote = (updates: Partial<Note>) => {
    if (!activeNote) return;
    setNotes(prev => prev.map(n => n.id === activeNote.id ? { ...n, ...updates, updatedAt: new Date().toISOString() } : n));
  };

  const handleAnalyze = async () => {
    if (!activeNote || !activeNote.content) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeNoteWithGemini(activeNote.content);
      updateActiveNote({
        scores: result.scores,
        phase: result.phase,
        tags: result.tags,
        aiAnalysis: result.analysis
      });
    } catch (e) {
      console.error("Analysis failed", e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const ScoreBar = ({ label, value, color }: { label: string; value: number; color: string }) => (
    <div className="mb-3">
      <div className="flex justify-between text-xs text-void-400 mb-1 font-mono">
        <span>{label}</span>
        <span>{value}/10</span>
      </div>
      <div className="h-1.5 w-full bg-void-800 rounded-full overflow-hidden">
        <div 
          className={`h-full transition-all duration-500 ${color}`} 
          style={{ width: `${value * 10}%` }}
        />
      </div>
    </div>
  );

  return (
    <div className="flex h-full bg-void-950">
      {/* Sidebar List */}
      <div className="w-72 border-r border-void-800 flex flex-col">
        <div className="p-4 border-b border-void-800 flex justify-between items-center">
          <h2 className="font-mono text-void-200 font-bold">ENTRIES</h2>
          <button onClick={handleCreateNote} className="p-1 hover:bg-void-800 rounded text-void-400 hover:text-white transition-colors">
            <span className="text-xl leading-none">+</span>
          </button>
        </div>
        <div className="flex-1 overflow-y-auto">
          {notes.map(note => (
            <div 
              key={note.id}
              onClick={() => setSelectedNoteId(note.id)}
              className={`p-4 border-b border-void-900 cursor-pointer hover:bg-void-900 transition-colors ${selectedNoteId === note.id ? 'bg-void-900 border-l-2 border-l-awakening' : ''}`}
            >
              <h3 className="text-void-200 text-sm font-medium truncate mb-1">{note.title}</h3>
              <div className="flex justify-between items-center">
                 <span className={`text-[10px] uppercase font-mono px-1.5 py-0.5 rounded ${
                   note.phase === 'collapse' ? 'bg-collapse/20 text-collapse' :
                   note.phase === 'awakening' ? 'bg-awakening/20 text-awakening' :
                   'bg-integration/20 text-integration'
                 }`}>{note.phase}</span>
                 <span className="text-[10px] text-void-500">{new Date(note.updatedAt).toLocaleDateString()}</span>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Editor Area */}
      {activeNote ? (
        <div className="flex-1 flex flex-col relative">
          <div className="p-6 border-b border-void-800 flex justify-between items-start bg-void-950/50 backdrop-blur-sm z-10">
            <div className="flex-1 mr-4">
              <input 
                value={activeNote.title}
                onChange={(e) => updateActiveNote({ title: e.target.value })}
                className="bg-transparent text-2xl font-bold text-void-100 placeholder-void-600 focus:outline-none w-full font-mono"
                placeholder="Entry Title..."
              />
              <div className="flex items-center space-x-2 mt-2 text-void-500 text-xs">
                 <Clock className="w-3 h-3" />
                 <span>Last edited: {new Date(activeNote.updatedAt).toLocaleString()}</span>
              </div>
            </div>
            <button 
              onClick={handleAnalyze}
              disabled={isAnalyzing || !activeNote.content}
              className={`flex items-center space-x-2 px-4 py-2 rounded-md font-mono text-xs uppercase tracking-wider transition-all ${
                isAnalyzing ? 'bg-void-800 text-void-500' : 'bg-awakening/10 text-awakening hover:bg-awakening/20 border border-awakening/20'
              }`}
            >
              <Sparkles className={`w-4 h-4 ${isAnalyzing ? 'animate-spin' : ''}`} />
              <span>{isAnalyzing ? 'Densifying...' : 'Analyze'}</span>
            </button>
          </div>

          <div className="flex-1 flex">
            <textarea
              value={activeNote.content}
              onChange={(e) => updateActiveNote({ content: e.target.value })}
              className="flex-1 bg-void-950 p-6 text-void-300 resize-none focus:outline-none leading-relaxed font-sans text-lg selection:bg-awakening/20"
              placeholder="Record your phenomenological observations..."
            />

            {/* Analysis Sidebar */}
            <div className="w-80 bg-void-900/50 border-l border-void-800 p-6 overflow-y-auto">
              <div className="mb-6">
                <h4 className="text-xs font-bold text-void-500 uppercase tracking-widest mb-4 font-mono">Resonance Metrics</h4>
                <ScoreBar label="Existential Dread" value={activeNote.scores.existentialDread} color="bg-collapse" />
                <ScoreBar label="Transcendental Yearning" value={activeNote.scores.transcendentalYearning} color="bg-awakening" />
                <ScoreBar label="Absurd Perspective" value={activeNote.scores.absurdPerspective} color="bg-orange-500" />
                <ScoreBar label="Void Resonance" value={activeNote.scores.voidResonance} color="bg-void-200" />
              </div>

              {activeNote.aiAnalysis && (
                <div className="mb-6 p-4 bg-void-950 border border-void-800 rounded-lg">
                   <div className="flex items-center space-x-2 mb-2 text-awakening">
                     <Activity className="w-4 h-4" />
                     <span className="text-xs font-bold font-mono uppercase">AI Synthesis</span>
                   </div>
                   <p className="text-sm text-void-300 italic leading-relaxed">
                     "{activeNote.aiAnalysis}"
                   </p>
                </div>
              )}

              <div className="flex flex-wrap gap-2">
                {activeNote.tags.map(tag => (
                  <span key={tag} className="flex items-center px-2 py-1 rounded bg-void-800 text-void-400 text-xs font-mono border border-void-700">
                    <Tag className="w-3 h-3 mr-1" />
                    {tag}
                  </span>
                ))}
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="flex-1 flex items-center justify-center text-void-600 font-mono">
           SELECT AN ENTRY OR INITIALIZE NEW STREAM
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Search, BrainCircuit, ArrowRight, Loader2 } from 'lucide-react';
import { ResearchQuery } from '../types';
import { deepResearch } from '../services/geminiService';

export const ResearchHub: React.FC = () => {
  const [query, setQuery] = useState('');
  const [history, setHistory] = useState<ResearchQuery[]>([]);
  const [loading, setLoading] = useState(false);

  const handleResearch = async () => {
    if (!query.trim()) return;
    setLoading(true);
    try {
      const response = await deepResearch(query);
      const newRecord: ResearchQuery = {
        id: crypto.randomUUID(),
        prompt: query,
        response,
        model: 'gemini-3-pro-preview',
        timestamp: new Date().toISOString(),
        isDeepResearch: true
      };
      setHistory([newRecord, ...history]);
      setQuery('');
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-void-950 p-6 max-w-5xl mx-auto w-full">
      <div className="mb-8">
        <h2 className="text-2xl font-bold text-void-100 font-mono mb-2">RESEARCH HUB</h2>
        <p className="text-void-400">Deep recursive densification via Gemini 3 Pro (Thinking Mode).</p>
      </div>

      {/* Input Area */}
      <div className="bg-void-900 p-1 rounded-lg border border-void-700 shadow-xl mb-8">
        <div className="relative">
          <textarea
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="w-full bg-void-950 text-void-200 p-4 min-h-[120px] rounded focus:outline-none font-sans text-lg resize-none"
            placeholder="Input philosophical inquiry for iterative saturation..."
          />
          <div className="absolute bottom-4 right-4 flex space-x-2">
            <div className="flex items-center px-3 py-1 bg-void-900 rounded border border-void-700 text-xs text-awakening font-mono">
              <BrainCircuit className="w-3 h-3 mr-2" />
              Thinking Mode: ON (32k Budget)
            </div>
            <button
              onClick={handleResearch}
              disabled={loading || !query}
              className="px-4 py-2 bg-void-100 text-void-950 font-bold rounded hover:bg-white transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center"
            >
              {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <ArrowRight className="w-4 h-4" />}
            </button>
          </div>
        </div>
      </div>

      {/* Results Feed */}
      <div className="flex-1 overflow-y-auto space-y-8 pr-2">
        {history.map(item => (
          <div key={item.id} className="group">
             <div className="flex items-center space-x-4 mb-4">
                <div className="h-px bg-void-800 flex-1"></div>
                <span className="text-xs font-mono text-void-500 uppercase">{new Date(item.timestamp).toLocaleTimeString()}</span>
                <div className="h-px bg-void-800 flex-1"></div>
             </div>

             <div className="mb-4">
               <h3 className="text-void-400 font-mono text-sm mb-2 uppercase tracking-widest">Inquiry</h3>
               <p className="text-lg text-void-200 font-serif italic border-l-2 border-void-700 pl-4">{item.prompt}</p>
             </div>

             <div className="bg-void-900/30 rounded-lg p-6 border border-void-800">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-awakening font-mono text-sm uppercase tracking-widest font-bold">Densification Result</h3>
                  <span className="text-[10px] bg-void-800 px-2 py-1 rounded text-void-400 font-mono">gemini-3-pro</span>
                </div>
                <div className="prose prose-invert prose-void max-w-none text-void-300 leading-relaxed whitespace-pre-wrap font-sans">
                  {item.response}
                </div>
             </div>
          </div>
        ))}
        {history.length === 0 && (
          <div className="text-center text-void-600 font-mono mt-20">
            [AWAITING INPUT VECTORS]
          </div>
        )}
      </div>
    </div>
  );
};

