import React from 'react';
import { Note } from '../types';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar } from 'recharts';

interface AnalysisWorkspaceProps {
  notes: Note[];
}

export const AnalysisWorkspace: React.FC<AnalysisWorkspaceProps> = ({ notes }) => {
  // Aggregate scores
  const aggregates = notes.reduce((acc, note) => ({
    dread: acc.dread + note.scores.existentialDread,
    transcendence: acc.transcendence + note.scores.transcendentalYearning,
    absurd: acc.absurd + note.scores.absurdPerspective,
    void: acc.void + note.scores.voidResonance,
    count: acc.count + 1
  }), { dread: 0, transcendence: 0, absurd: 0, void: 0, count: 0 });

  const radarData = aggregates.count ? [
    { subject: 'Existential Dread', A: aggregates.dread / aggregates.count, fullMark: 10 },
    { subject: 'Transcendental Yearning', A: aggregates.transcendence / aggregates.count, fullMark: 10 },
    { subject: 'Absurd Perspective', A: aggregates.absurd / aggregates.count, fullMark: 10 },
    { subject: 'Void Resonance', A: aggregates.void / aggregates.count, fullMark: 10 },
  ] : [];

  const barData = notes.slice(0, 10).map(n => ({
    name: n.title.substring(0, 10) + '...',
    Dread: n.scores.existentialDread,
    Transcendence: n.scores.transcendentalYearning
  }));

  return (
    <div className="p-8 h-full overflow-y-auto bg-void-950">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-void-100 font-mono mb-2">ANALYSIS WORKSPACE</h1>
        <p className="text-void-400">Quantitative metrics of qualitative phenomenology.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Radar Chart */}
        <div className="bg-void-900 border border-void-800 p-6 rounded-lg h-96">
          <h3 className="text-void-400 font-mono text-xs uppercase tracking-widest mb-4">Average Resonance Profile</h3>
          <ResponsiveContainer width="100%" height="100%">
            <RadarChart cx="50%" cy="50%" outerRadius="80%" data={radarData}>
              <PolarGrid stroke="#3f3f46" />
              <PolarAngleAxis dataKey="subject" tick={{ fill: '#a1a1aa', fontSize: 12 }} />
              <PolarRadiusAxis angle={30} domain={[0, 10]} stroke="#71717a" />
              <Radar name="Average" dataKey="A" stroke="#a855f7" fill="#a855f7" fillOpacity={0.3} />
              <Tooltip contentStyle={{ backgroundColor: '#18181b', borderColor: '#27272a', color: '#fff' }} />
            </RadarChart>
          </ResponsiveContainer>
        </div>

        {/* Bar Chart */}
        <div className="bg-void-900 border border-void-800 p-6 rounded-lg h-96">
          <h3 className="text-void-400 font-mono text-xs uppercase tracking-widest mb-4">Dread vs. Transcendence (Recent Entries)</h3>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={barData}>
              <XAxis dataKey="name" stroke="#71717a" fontSize={12} />
              <YAxis stroke="#71717a" fontSize={12} />
              <Tooltip cursor={{fill: '#27272a'}} contentStyle={{ backgroundColor: '#18181b', borderColor: '#27272a', color: '#fff' }} />
              <Bar dataKey="Dread" fill="#ef4444" radius={[4, 4, 0, 0]} />
