import React, { useMemo } from 'react';
import { Note } from '../types';

interface ConceptMapProps {
  notes: Note[];
}

export const ConceptMap: React.FC<ConceptMapProps> = ({ notes }) => {
  // Generate a pseudo-random layout based on scores
  const nodes = useMemo(() => {
    return notes.map(note => {
      // X axis: Dread vs Transcendence
      // Y axis: Void vs Absurd
      const x = (note.scores.transcendentalYearning - note.scores.existentialDread) * 40 + 400; // Center 400
      const y = (note.scores.voidResonance - note.scores.absurdPerspective) * 40 + 300; // Center 300

      return {
        ...note,
        x,
        y
      };
    });
  }, [notes]);

  return (
    <div className="h-full bg-void-950 p-6 flex flex-col">
       <div className="mb-4 flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-void-100 font-mono">CONCEPTUAL TOPOLOGY</h2>
          <p className="text-void-400 text-sm">Spatial representation of entries based on score vectors.</p>
        </div>
        <div className="text-xs text-void-500 font-mono text-right">
          X: Dread (-) <-> Transcendence (+)<br/>
          Y: Absurd (-) <-> Void (+)
        </div>
      </div>

      <div className="flex-1 border border-void-800 rounded-lg bg-void-900 relative overflow-hidden flex items-center justify-center">
        <svg viewBox="0 0 800 600" className="w-full h-full">
           {/* Grid Lines */}
           <line x1="400" y1="0" x2="400" y2="600" stroke="#27272a" strokeWidth="1" />
           <line x1="0" y1="300" x2="800" y2="300" stroke="#27272a" strokeWidth="1" />

           {/* Nodes */}
           {nodes.map((node) => (
             <g key={node.id} className="cursor-pointer hover:opacity-80 transition-opacity">
               <circle 
                 cx={node.x} 
                 cy={node.y} 
                 r={node.scores.voidResonance + 5} 
                 fill={
                    node.phase === 'collapse' ? '#ef4444' :
                    node.phase === 'awakening' ? '#a855f7' :
                    '#10b981'
                 }
                 fillOpacity={0.6}
                 stroke={
                    node.phase === 'collapse' ? '#ef4444' :
                    node.phase === 'awakening' ? '#a855f7' :
                    '#10b981'
                 }
                 strokeWidth={2}
               />
               <text 
                 x={node.x} 
                 y={node.y - 15} 
                 textAnchor="middle" 
                 fill="#e4e4e7" 
                 fontSize="10"
                 fontFamily="monospace"
               >
                 {node.title.substring(0, 15)}
               </text>
             </g>
           ))}
        </svg>
      </div>
    </div>
  );
};

