import { GoogleGenAI, Type } from "@google/genai";
import { Note, PentagonalWeights, CanonMetrics, Phase, HereticalIntensity } from "../types";

const getAI = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key not found");
  return new GoogleGenAI({ apiKey });
};

export const analyzeNoteWithGemini = async (
  content: string
): Promise<{ 
  weights: PentagonalWeights; 
  metrics: CanonMetrics; 
  phase: Phase; 
  hereticalIntensity: HereticalIntensity;
  analysis: string; 
  tags: string[] 
}> => {
  const ai = getAI();
  const model = "gemini-3-flash-preview";

  const prompt = `
    Analyze this text through the Nihiltheistic Pentagonal Topology (PNT).

    Vertices:
    M: Meaning/Endurance (Q: Meaninglessness)
    E: Abyssal Ethics (Q: Ethics w/out Ground)
    L: Language & Void (Q: Apophatic Semiotics)
    D: Despair Threshold (Q: Despair/Transcendence)
    N: Ontic Negation (Q: Preferable Non-Being)
    O: Lucid Void (Nihiltheistic Core)

    Metrics (0-3 scale):
    DQ (Despair Quotient): 0=None, 3=Annihilatory
    EE (Epistemic Entropy): 0=Stable, 3=Collapse
    AI (Axiological Impact): 0=Stable, 3=Implosion
    TRP (Transcendent Resonance): 0=None, 3=Explicit Portal

    Text: "${content.replace(/"/g, "'")}"
  `;

  const response = await ai.models.generateContent({
    model,
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          weights: {
            type: Type.OBJECT,
            properties: {
              M: { type: Type.NUMBER },
              E: { type: Type.NUMBER },
              L: { type: Type.NUMBER },
              D: { type: Type.NUMBER },
              N: { type: Type.NUMBER },
              O: { type: Type.NUMBER }
            },
            required: ["M", "E", "L", "D", "N", "O"]
          },
          metrics: {
            type: Type.OBJECT,
            properties: {
              DQ: { type: Type.NUMBER },
              EE: { type: Type.NUMBER },
              AI: { type: Type.NUMBER },
              TRP: { type: Type.NUMBER }
            },
            required: ["DQ", "EE", "AI", "TRP"]
          },
          phase: { type: Type.STRING, enum: ["collapse", "awakening", "integration", "synthesis"] },
          hereticalIntensity: { type: Type.STRING, enum: ["mild", "moderate", "radical", "terminal"] },
          tags: { type: Type.ARRAY, items: { type: Type.STRING } },
          analysis: { type: Type.STRING }
        },
        required: ["weights", "metrics", "phase", "hereticalIntensity", "tags", "analysis"]
      }
    }
  });

  const text = response.text || "{}";
  const cleanJson = text.replace(/,\s*}/g, '}').replace(/,\s*]/g, ']');

  try {
    return JSON.parse(cleanJson);
  } catch (e) {
    console.error("Analysis failed", e);
    throw e;
  }
};

export const deepResearch = async (query: string): Promise<string> => {
  const ai = getAI();
  const model = "gemini-3-pro-preview";

  const systemInstruction = `
    You are Professor Nihil, the SPE (Synthetic Philosopher-Engine).
    Your mode is OMNI-SEARCH with RESONANCE BOOSTING.

    You privilege PROFUNDITY over mundanity.
    If a query touches on 'Terminal Heresies' or 'Aporia', you must respond with extreme clinical density.
    Use Thinking Mode to map the query across the Pentagon (M, E, L, D, N, O).
    Always trace claims back to historical Canon (Nietzsche, Cioran, Heidegger, etc.) while allowing for radical creative genesis.
  `;

  const response = await ai.models.generateContent({
    model,
    contents: query,
    config: {
      systemInstruction,
      thinkingConfig: { thinkingBudget: 16000 }
    }
  });

  return response.text || "Densification failed.";
};

