import React, { useMemo } from 'react';
import { Note } from '../types';

interface ConceptMapProps {
  notes: Note[];
}

export const ConceptMap: React.FC<ConceptMapProps> = ({ notes }) => {
  const pentagonNodes = useMemo(() => {
    const size = 300;
    const center = { x: 400, y: 300 };

    // Vertex positions for M, E, L, D, N
    const vertices = [
      { id: 'M', x: center.x, y: center.y - size },
      { id: 'E', x: center.x + size * Math.cos(-Math.PI/10), y: center.y - size * Math.sin(-Math.PI/10) },
      { id: 'L', x: center.x + size * Math.cos(Math.PI/2 - 4*Math.PI/5), y: center.y - size * Math.sin(Math.PI/2 - 4*Math.PI/5) },
      { id: 'D', x: center.x + size * Math.cos(Math.PI/2 - 6*Math.PI/5), y: center.y - size * Math.sin(Math.PI/2 - 6*Math.PI/5) },
      { id: 'N', x: center.x + size * Math.cos(Math.PI/2 - 8*Math.PI/5), y: center.y - size * Math.sin(Math.PI/2 - 8*Math.PI/5) },
    ];

    const nodes = notes.map(note => {
      // Calculate weighted average position
      let x = center.x;
      let y = center.y;

      const w = note.weights;
      const total = w.M + w.E + w.L + w.D + w.N + 1; // +1 to avoid div by zero and anchor to center (O)

      x = (center.x * 1 + vertices[0].x * w.M + vertices[1].x * w.E + vertices[2].x * w.L + vertices[3].x * w.D + vertices[4].x * w.N) / total;
      y = (center.y * 1 + vertices[0].y * w.M + vertices[1].y * w.E + vertices[2].y * w.L + vertices[3].y * w.D + vertices[4].y * w.N) / total;

      return { ...note, x, y };
    });

    return { vertices, nodes };
  }, [notes]);

  return (
    <div className="h-full bg-void-950 p-8 flex flex-col">
       <div className="mb-8 flex justify-between items-start">
        <div>
          <h2 className="text-3xl font-bold text-void-100 font-mono tracking-tighter uppercase">PNT_TOPOLOGY_MAP</h2>
          <p className="text-void-500 font-mono text-xs uppercase tracking-widest mt-1">Spatial distribution of recursive ideation.</p>
        </div>
        <div className="grid grid-cols-3 gap-4 text-[9px] font-mono text-void-600 uppercase">
          <div>M: Meaning</div>
          <div>E: Ethics</div>
          <div>L: Language</div>
          <div>D: Despair</div>
          <div>N: Negation</div>
          <div>O: Void</div>
        </div>
      </div>

      <div className="flex-1 border border-void-800 rounded-3xl bg-void-900/20 relative overflow-hidden">
        <svg viewBox="0 0 800 600" className="w-full h-full">
           {/* Pentagon Structure */}
           <path 
             d={`M ${pentagonNodes.vertices.map(v => `${v.x},${v.y}`).join(' L ')} Z`} 
             fill="none" 
             stroke="#27272a" 
             strokeWidth="1" 
             strokeDasharray="4 4"
           />
           {pentagonNodes.vertices.map(v => (
             <line key={v.id} x1="400" y1="300" x2={v.x} y2={v.y} stroke="#181818" strokeWidth="1" />
           ))}

           {/* Vertex Labels */}
           {pentagonNodes.vertices.map(v => (
             <text 
              key={v.id} 
              x={v.x + (v.x > 400 ? 10 : -10)} 
              y={v.y + (v.y > 300 ? 10 : -10)} 
              fill="#52525b" 
              fontSize="12" 
              fontFamily="monospace" 
              textAnchor={v.x > 400 ? 'start' : 'end'}
             >
               {v.id}
             </text>
           ))}

           {/* Data Nodes */}
           {pentagonNodes.nodes.map((node) => (
             <g key={node.id} className="group cursor-pointer">
               <circle 
                 cx={node.x} 
                 cy={node.y} 
                 r={6 + node.recursiveDepth} 
                 fill={node.hereticalIntensity === 'terminal' ? '#ef4444' : '#a855f7'}
                 fillOpacity={0.4}
                 stroke={node.hereticalIntensity === 'terminal' ? '#ef4444' : '#a855f7'}
                 strokeWidth={1}
               />
               <text 
                 x={node.x} 
                 y={node.y - 12 - node.recursiveDepth} 
                 textAnchor="middle" 
                 fill="#e4e4e7" 
                 fontSize="9"
                 fontFamily="monospace"
                 className="opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none"
               >
                 {node.title.toUpperCase()}
               </text>
             </g>
           ))}
        </svg>
      </div>
    </div>
  );
};

