import React, { useMemo, useState } from 'react';
import { Note } from '../types';
import { synthesizeTwoConcepts } from '../services/geminiService';
import { Zap, Loader2, X, Info } from 'lucide-react';

interface ConceptMapProps {
  notes: Note[];
}

export const ConceptMap: React.FC<ConceptMapProps> = ({ notes }) => {
  const [selectedNodeIds, setSelectedNodeIds] = useState<string[]>([]);
  const [synthesis, setSynthesis] = useState<string | null>(null);
  const [isSynthesizing, setIsSynthesizing] = useState(false);

  const constellation = useMemo(() => {
    const size = 320;
    const center = { x: 450, y: 350 };

    const vertices = [
      { id: 'M', x: center.x, y: center.y - size },
      { id: 'E', x: center.x + size * Math.cos(-Math.PI/10), y: center.y - size * Math.sin(-Math.PI/10) },
      { id: 'L', x: center.x + size * Math.cos(Math.PI/2 - 4*Math.PI/5), y: center.y - size * Math.sin(Math.PI/2 - 4*Math.PI/5) },
      { id: 'D', x: center.x + size * Math.cos(Math.PI/2 - 6*Math.PI/5), y: center.y - size * Math.sin(Math.PI/2 - 6*Math.PI/5) },
      { id: 'N', x: center.x + size * Math.cos(Math.PI/2 - 8*Math.PI/5), y: center.y - size * Math.sin(Math.PI/2 - 8*Math.PI/5) },
    ];

    const nodes = notes.map((note, idx) => {
      let x = center.x;
      let y = center.y;
      const w = note.weights;
      const total = w.M + w.E + w.L + w.D + w.N + 1;

      x = (center.x * 2 + vertices[0].x * w.M + vertices[1].x * w.E + vertices[2].x * w.L + vertices[3].x * w.D + vertices[4].x * w.N) / (total + 1);
      y = (center.y * 2 + vertices[0].y * w.M + vertices[1].y * w.E + vertices[2].y * w.L + vertices[3].y * w.D + vertices[4].y * w.N) / (total + 1);

      // Add slight jiggle for visual variety
      x += (Math.sin(idx) * 30);
      y += (Math.cos(idx) * 30);

      return { ...note, x, y };
    });

    const edges: { source: any, target: any }[] = [];
    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < nodes.length; j++) {
        const sharedTags = nodes[i].tags.filter(tag => nodes[j].tags.includes(tag));
        if (sharedTags.length > 0) {
          edges.push({ source: nodes[i], target: nodes[j] });
        }
      }
    }

    return { vertices, nodes, edges };
  }, [notes]);

  const handleNodeClick = (id: string) => {
    setSelectedNodeIds(prev => {
      if (prev.includes(id)) return prev.filter(i => i !== id);
      if (prev.length >= 2) return [prev[1], id];
      return [...prev, id];
    });
  };

  const handleSynthesize = async () => {
    if (selectedNodeIds.length !== 2) return;
    const noteA = notes.find(n => n.id === selectedNodeIds[0]);
    const noteB = notes.find(n => n.id === selectedNodeIds[1]);
    if (!noteA || !noteB) return;

    setIsSynthesizing(true);
    setSynthesis(null);
    try {
      const result = await synthesizeTwoConcepts(noteA, noteB);
      setSynthesis(result);
    } catch (e) {
      setSynthesis("CRITICAL_COLLISION_ERROR: Entropic noise detected.");
    } finally {
      setIsSynthesizing(false);
    }
  };

  return (
    <div className="h-full bg-cosmic-void flex flex-col relative overflow-hidden">
      <div className="p-10 flex justify-between items-start z-10">
        <div>
          <h2 className="text-4xl font-bold text-white font-mono tracking-tighter uppercase mb-2">Topology_Resonance</h2>
          <p className="text-void-500 font-mono text-[10px] uppercase tracking-[0.4em]">Spreading Nodes / Neural Synthesis</p>
        </div>
        <div className="flex space-x-4 items-center">
          {selectedNodeIds.length === 2 && (
            <button 
              onClick={handleSynthesize}
              disabled={isSynthesizing}
              className="group flex items-center space-x-3 bg-neon-purple text-white px-6 py-3 rounded-full font-mono text-xs uppercase tracking-widest shadow-neon-purple/40 hover:scale-105 active:scale-95 transition-all animate-pulse"
            >
              {isSynthesizing ? <Loader2 className="w-4 h-4 animate-spin" /> : <Zap className="w-4 h-4" />}
              <span>Initiate_Synthesis</span>
            </button>
          )}
          <div className="glass px-6 py-3 rounded-xl flex space-x-6 text-[9px] font-mono text-void-400 uppercase tracking-widest border border-white/5">
            <span className="flex items-center"><div className="w-1.5 h-1.5 rounded-full bg-neon-cyan mr-2"></div> Meaning</span>
            <span className="flex items-center"><div className="w-1.5 h-1.5 rounded-full bg-neon-purple mr-2"></div> Ethics</span>
            <span className="flex items-center"><div className="w-1.5 h-1.5 rounded-full bg-neon-teal mr-2"></div> Void</span>
          </div>
        </div>
      </div>

      <div className="flex-1 relative cursor-grab active:cursor-grabbing">
        <svg viewBox="0 0 900 700" className="w-full h-full drop-shadow-2xl">
           <defs>
              <filter id="neon-glow" x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation="5" result="blur" />
                <feComposite in="SourceGraphic" in2="blur" operator="over" />
              </filter>
              <radialGradient id="nebulaRadial" cx="50%" cy="50%" r="50%">
                <stop offset="0%" stopColor="#22d3ee" stopOpacity="0.1" />
                <stop offset="100%" stopColor="#000000" stopOpacity="0" />
              </radialGradient>
           </defs>

           <circle cx="450" cy="350" r="350" fill="url(#nebulaRadial)" />

           {/* Backdrop Edges */}
           {constellation.edges.map((edge, i) => (
             <line 
               key={`edge-${i}`}
               x1={edge.source.x} y1={edge.source.y}
               x2={edge.target.x} y2={edge.target.y}
               stroke="rgba(34, 211, 238, 0.15)"
               strokeWidth="1"
               strokeDasharray="5 5"
             />
           ))}

           {/* Active Synthesis Connection */}
           {selectedNodeIds.length === 2 && (
             <line 
                x1={constellation.nodes.find(n => n.id === selectedNodeIds[0])?.x}
                y1={constellation.nodes.find(n => n.id === selectedNodeIds[0])?.y}
                x2={constellation.nodes.find(n => n.id === selectedNodeIds[1])?.x}
                y2={constellation.nodes.find(n => n.id === selectedNodeIds[1])?.y}
                stroke="#a855f7"
                strokeWidth="3"
                filter="url(#neon-glow)"
                className="animate-pulse"
             />
           )}

           {/* Topology Nodes */}
           {constellation.nodes.map((node) => {
             const isSelected = selectedNodeIds.includes(node.id);
             return (
               <g key={node.id} className="group cursor-pointer" onClick={() => handleNodeClick(node.id)}>
                 {/* Glow Layer */}
                 <circle 
                   cx={node.x} 
                   cy={node.y} 
                   r={12 + node.recursiveDepth * 2} 
                   fill={isSelected ? '#22d3ee' : '#22d3ee'}
                   fillOpacity={isSelected ? 0.4 : 0.05}
                   className="transition-all duration-500"
                 />
                 {/* Inner Dot */}
                 <circle 
                   cx={node.x} 
                   cy={node.y} 
                   r={5 + node.recursiveDepth} 
                   fill={isSelected ? '#fff' : '#22d3ee'}
                   stroke={isSelected ? '#fff' : '#22d3ee'}
                   strokeWidth="2"
                   className="transition-all duration-300 group-hover:r-8"
                 />
                 {/* Label */}
                 <text 
                   x={node.x} 
                   y={node.y + 25 + node.recursiveDepth} 
                   textAnchor="middle" 
                   fill={isSelected ? '#fff' : '#52525b'} 
                   fontSize="9"
                   fontWeight="bold"
                   fontFamily="monospace"
                   className={`transition-opacity pointer-events-none uppercase tracking-widest ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
                 >
                   {node.title}
                 </text>
               </g>
