           })}
        </svg>
      </div>

      {synthesis && (
        <div className="absolute inset-0 bg-black/80 backdrop-blur-2xl flex items-center justify-center p-12 z-50 animate-in fade-in zoom-in duration-500">
          <div className="max-w-3xl w-full glass-card rounded-[40px] p-12 shadow-2xl relative overflow-hidden">
