              <X className="w-8 h-8" />
            </button>
            <div className="flex items-center space-x-6 mb-10">
              <div className="w-16 h-16 bg-neon-purple rounded-2xl flex items-center justify-center shadow-neon-purple/40">
                <Zap className="w-8 h-8 text-white" />
              </div>
              <div>
                <h3 className="text-2xl font-bold font-mono tracking-tighter text-white uppercase">Neural_Synergy_Achieved</h3>
                <p className="text-[10px] text-neon-purple font-mono tracking-[0.3em] uppercase">Density Critical / Axiomatic Shift</p>
              </div>
