  const [notes, setNotes] = useState<Note[]>(initialNotes);
  const [sources, setSources] = useState<Source[]>([]);
  const [selectedSource, setSelectedSource] = useState<Source | null>(null);

  const handleSourceAdded = (source: Source) => {
    setSources(prev => [source, ...prev]);
  };

  const renderView = () => {
    switch (currentView) {
      case 'dashboard': return <Dashboard notes={notes} />;
      case 'chat': return <ChatInterface />;
      case 'research': return <ResearchHub />;
      case 'library': return (
        <div className="p-12 h-full overflow-y-auto grid grid-cols-1 xl:grid-cols-3 gap-12">
          <div className="xl:col-span-1 space-y-12">
            <KnowledgeIngestion onSourceAdded={handleSourceAdded} />
            <LibraryBrowser sources={sources} onSelect={setSelectedSource} />
          </div>
          <div className="xl:col-span-2">
            {selectedSource ? (
              <div className="glass-card rounded-[48px] p-16 animate-in fade-in slide-in-from-right-12 duration-500 border border-white/10 shadow-2xl">
                <div className="flex justify-between items-center mb-12">
                  <h2 className="text-4xl font-bold text-white font-mono tracking-tighter">{selectedSource.title}</h2>
                  <button onClick={() => setSelectedSource(null)} className="text-void-500 hover:text-white font-mono text-xs uppercase tracking-widest px-4 py-2 bg-white/5 rounded-full transition-all">Close_Terminal</button>
                </div>
                <div className="space-y-12">
                  <section>
                    <h4 className="text-[11px] font-bold text-void-500 uppercase tracking-[0.4em] mb-6 font-mono">Conceptual_Axiom</h4>
                    <div className="glass bg-black/40 p-8 rounded-3xl border border-white/5 font-serif italic text-2xl text-void-100 leading-relaxed">
                      {selectedSource.summaries[0]?.text || "NO_SUMMARY_DATA"}
                    </div>
                  </section>
                  <section>
                    <h4 className="text-[11px] font-bold text-void-500 uppercase tracking-[0.4em] mb-6 font-mono">Detected_Aporia</h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {selectedSource.questions.map((q, i) => (
                        <div key={i} className="p-6 bg-void-900/50 rounded-2xl border border-white/5 text-sm text-void-300 font-mono">
                          <span className="text-neon-cyan font-bold mr-3">APORIA_{i+1}:</span> {q.text}
                        </div>
                      ))}
                    </div>
                  </section>
                </div>
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center glass border border-white/5 rounded-[48px] bg-black/20 opacity-40">
                <div className="w-16 h-16 border-2 border-void-800 rounded-full flex items-center justify-center mb-6">
                  <div className="w-2 h-2 bg-void-600 rounded-full"></div>
                </div>
                <p className="text-xs font-mono text-void-700 uppercase tracking-[0.6em]">Select_Source_Vector</p>
              </div>
            )}
          </div>
        </div>
      );
      case 'summaries': return <div className="p-12 h-full overflow-y-auto max-w-6xl mx-auto"><SummaryFeed sources={sources} /></div>;
      case 'digest': return <DigestView sources={sources} />;
      case 'notes': return <NoteEditor notes={notes} setNotes={setNotes} />;
      case 'concepts': return <ConceptMap notes={notes} />;
      case 'analysis': return <AnalysisWorkspace notes={notes} />;
      case 'framework': return <PhilosophicalFramework />;
      default: return <Dashboard notes={notes} />;
    }
  };

  return (
    <div className="flex h-screen bg-[#000000] text-void-100 overflow-hidden font-sans select-none">
      <div className="scan-line"></div>
      <Sidebar currentView={currentView} onViewChange={setCurrentView} />
      <main className="flex-1 h-full overflow-hidden relative">
        {renderView()}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Search, BrainCircuit, ArrowRight, Loader2, Target, Info, Sparkles } from 'lucide-react';
import { ResearchQuery } from '../types';
import { deepResearch } from '../services/geminiService';

export const ResearchHub: React.FC = () => {
  const [query, setQuery] = useState('');
  const [history, setHistory] = useState<ResearchQuery[]>([]);
  const [loading, setLoading] = useState(false);
  const [currentCycle, setCurrentCycle] = useState(0);

  const handleResearch = async () => {
    if (!query.trim()) return;
    setLoading(true);
    setCurrentCycle(1);

    try {
      // Internal loop simulation
      const response = await deepResearch(query);
      const newRecord: ResearchQuery = {
        id: crypto.randomUUID(),
        prompt: query,
        response,
        model: 'gemini-3-pro-preview',
        timestamp: new Date().toISOString(),
        resonanceBoost: true
      };
      setHistory([newRecord, ...history]);
      setQuery('');
      setCurrentCycle(0);
    } catch (e) {
      console.error(e);
      setCurrentCycle(0);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#000000] p-12 max-w-[1400px] mx-auto w-full relative">
      <header className="mb-12">
        <h2 className="text-5xl font-black text-white font-mono tracking-tighter uppercase mb-4">Densification_Engine</h2>
        <div className="flex items-center space-x-4">
           <div className="h-1 w-1 bg-neon-purple rounded-full animate-ping"></div>
           <p className="text-void-500 font-mono text-[11px] uppercase tracking-[0.5em]">Iterative_Saturation_Protocol // Thinking_Budget: 16k</p>
        </div>
      </header>

      <div className="glass-card p-2 rounded-[40px] border border-white/5 shadow-2xl mb-12 focus-within:border-neon-purple transition-all">
        <div className="relative">
          <textarea
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="w-full bg-black/40 text-void-100 p-10 min-h-[160px] rounded-[36px] focus:outline-none font-sans text-xl leading-relaxed resize-none placeholder-void-800"
            placeholder="Input philosophical inquiry for iterative saturation..."
          />
          <div className="absolute bottom-10 right-10 flex space-x-4">
            {loading && (
              <div className="flex items-center px-6 py-3 bg-neon-purple/10 rounded-full border border-neon-purple/20 text-[10px] text-neon-purple font-mono uppercase tracking-widest animate-pulse">
                <BrainCircuit className="w-4 h-4 mr-3" />
                Cycle_{currentCycle}: Processing_Recursion
              </div>
            )}
            <button
              onClick={handleResearch}
              disabled={loading || !query}
              className="w-14 h-14 bg-white text-black rounded-full flex items-center justify-center hover:bg-neon-purple hover:text-white disabled:opacity-20 transition-all duration-500 shadow-2xl"
            >
              {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <ArrowRight className="w-6 h-6" />}
            </button>
          </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto space-y-12 pr-4 custom-scrollbar">
        {history.map(item => (
          <div key={item.id} className="group animate-in fade-in slide-in-from-bottom-8 duration-700">
             <div className="flex items-center space-x-6 mb-8 opacity-40 group-hover:opacity-100 transition-opacity">
                <div className="h-[1px] bg-void-800 flex-1"></div>
                <div className="flex items-center space-x-3 text-[10px] font-mono text-void-500 uppercase tracking-widest">
                   <Target className="w-3 h-3" />
                   <span>VECTOR_TIMESTAMP: {new Date(item.timestamp).toLocaleTimeString()}</span>
                </div>
                <div className="h-[1px] bg-void-800 flex-1"></div>
             </div>

             <div className="mb-10 px-10">
               <h3 className="text-void-600 font-mono text-[10px] uppercase tracking-[0.4em] mb-4 font-bold">Inquiry_Vector</h3>
               <p className="text-3xl text-white font-serif italic border-l-4 border-neon-purple/40 pl-10 leading-snug">
                 {item.prompt}
               </p>
             </div>

             <div className="glass-card rounded-[48px] p-16 border border-white/5 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-12 opacity-[0.03]">
                  <Sparkles className="w-64 h-64 text-neon-purple" />
                </div>
                <div className="flex items-center justify-between mb-12">
                  <div className="flex items-center space-x-4">
                     <div className="w-10 h-10 bg-neon-purple rounded-xl flex items-center justify-center shadow-neon-purple/20">
                        <Info className="w-5 h-5 text-white" />
                     </div>
                     <h3 className="text-white font-mono text-xs uppercase tracking-[0.3em] font-bold">Densification_Output</h3>
                  </div>
                  <span className="text-[10px] bg-white/5 px-4 py-1.5 rounded-full text-void-500 font-mono tracking-widest border border-white/5">PRO_v3_THINKING</span>
                </div>
                <div className="prose prose-invert prose-lg max-w-none text-void-200 leading-[1.8] font-sans whitespace-pre-wrap">
                  {item.response}
                </div>
             </div>
          </div>
        ))}
        {history.length === 0 && (
          <div className="flex flex-col items-center justify-center py-40 opacity-20">
            <BrainCircuit className="w-20 h-20 text-void-700 mb-8" />
            <p className="font-mono text-xs uppercase tracking-[0.6em]">Awaiting_Cognitive_Input</p>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Send, Bot, User, Sparkles, RefreshCcw, Loader2, Brain } from 'lucide-react';
import { createChatSession } from '../services/geminiService';
import { ChatMessage } from '../types';
import { Chat, GenerateContentResponse } from "@google/genai";

export const ChatInterface: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: 'init',
      role: 'system',
      content: 'PHILOVOID_LINK_ESTABLISHED. RECURSIVE_LOOP_ACTIVE.',
      timestamp: new Date().toISOString()
    }
  ]);
  const [input, setInput] = useState('');
  const [isStreaming, setIsStreaming] = useState(false);
  const chatSessionRef = useRef<Chat | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatSessionRef.current = createChatSession();
  }, []);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isStreaming) return;

    const userMsg: ChatMessage = {
      id: crypto.randomUUID(),
      role: 'user',
      content: input,
      timestamp: new Date().toISOString()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsStreaming(true);

    try {
      if (!chatSessionRef.current) chatSessionRef.current = createChatSession();

      const modelMsgId = crypto.randomUUID();
      const initialModelMsg: ChatMessage = {
        id: modelMsgId,
        role: 'model',
        content: '',
        timestamp: new Date().toISOString(),
        isStreaming: true
      };

      setMessages(prev => [...prev, initialModelMsg]);

      const result = await chatSessionRef.current.sendMessageStream({ message: userMsg.content });

      let accumulatedText = '';

      for await (const chunk of result) {
        const c = chunk as GenerateContentResponse;
        if (c.text) {
          accumulatedText += c.text;
          setMessages(prev => prev.map(msg => 
            msg.id === modelMsgId ? { ...msg, content: accumulatedText } : msg
          ));
        }
      }

      setMessages(prev => prev.map(msg => 
        msg.id === modelMsgId ? { ...msg, isStreaming: false } : msg
      ));

    } catch (error) {
      console.error(error);
      setMessages(prev => [...prev, {
        id: crypto.randomUUID(),
        role: 'system',
        content: 'SIGNAL_LOST: Connection to the Void severed. Re-initialize protocol.',
        timestamp: new Date().toISOString()
      }]);
    } finally {
      setIsStreaming(false);
    }
  };

  const handleReset = () => {
    chatSessionRef.current = createChatSession();
    setMessages([{
      id: crypto.randomUUID(),
      role: 'system',
      content: 'SYMBIONT_RESET_COMPLETE. Memory buffers purged.',
      timestamp: new Date().toISOString()
    }]);
  };

  return (
    <div className="flex flex-col h-full bg-[#000000] max-w-6xl mx-auto w-full border-x border-white/5 relative">
      <header className="p-10 border-b border-white/5 glass sticky top-0 z-20 flex justify-between items-center">
        <div>
          <h2 className="text-3xl font-bold text-white font-mono tracking-tighter">Dialectic_Engine</h2>
          <p className="text-void-500 text-[10px] font-mono uppercase tracking-[0.4em] mt-1">Recursive_Ontological_Link</p>
        </div>
        <button onClick={handleReset} className="p-3 text-void-600 hover:text-neon-red hover:bg-neon-red/10 rounded-full transition-all">
          <RefreshCcw className="w-5 h-5" />
        </button>
      </header>

      <div className="flex-1 overflow-y-auto p-12 space-y-10 custom-scrollbar">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in duration-500`}>
            <div className={`flex max-w-[85%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'} items-start gap-6`}>
              <div className={`w-12 h-12 rounded-2xl flex items-center justify-center flex-shrink-0 shadow-2xl ${
                msg.role === 'user' ? 'bg-void-800' : 
                msg.role === 'model' ? 'bg-neon-purple shadow-neon-purple/20' : 'bg-void-900 border border-void-800'
              }`}>
                {msg.role === 'user' ? <User className="w-6 h-6 text-void-400" /> : 
                 msg.role === 'model' ? <Bot className="w-6 h-6 text-white" /> :
                 <Sparkles className="w-5 h-5 text-void-600" />}
              </div>

              <div className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                <div className={`px-8 py-6 rounded-3xl font-sans text-lg leading-[1.6] whitespace-pre-wrap transition-all ${
                  msg.role === 'user' 
                    ? 'bg-void-900 text-void-100 border border-white/5' 
                    : msg.role === 'model'
                    ? 'glass-card text-void-200 border-l-4 border-neon-purple pl-10'
                    : 'text-void-600 text-[11px] font-mono tracking-widest uppercase py-2 px-0'
                }`}>
                  {msg.content}
                  {msg.isStreaming && <span className="inline-block w-2 h-6 ml-2 bg-neon-purple animate-pulse align-middle"></span>}
                </div>
                {msg.role !== 'system' && (
                   <span className="text-[9px] text-void-700 mt-3 font-mono uppercase tracking-[0.2em]">
                     {new Date(msg.timestamp).toLocaleTimeString()}
                   </span>
                )}
              </div>
            </div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-10 border-t border-white/5 bg-black/80 backdrop-blur-xl">
        <div className="relative glass-card rounded-[32px] border border-white/5 focus-within:border-neon-purple/40 shadow-2xl transition-all p-2">
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
            placeholder="Interrogate the Symbiont..."
            className="w-full bg-transparent text-void-100 p-6 pr-20 min-h-[80px] max-h-[250px] resize-none focus:outline-none font-sans text-xl leading-relaxed"
            disabled={isStreaming}
          />
          <button
            onClick={handleSend}
            disabled={!input.trim() || isStreaming}
            className="absolute right-6 bottom-6 w-14 h-14 bg-white text-black rounded-2xl hover:bg-neon-purple hover:text-white disabled:opacity-10 transition-all duration-500 shadow-xl flex items-center justify-center"
          >
            {isStreaming ? <Loader2 className="w-6 h-6 animate-spin" /> : <Send className="w-6 h-6" />}
          </button>
        </div>
        <div className="flex justify-between items-center mt-6 px-4">
          <div className="flex items-center space-x-3 text-[10px] text-void-700 font-mono uppercase tracking-[0.3em]">
             <Brain className="w-3 h-3" />
             <span>Active_Nodes: Global_Mesh</span>
          </div>
          <p className="text-[10px] text-void-800 font-mono uppercase tracking-[0.3em]">
            PRO_v3 // DENSIFICATION_ACTIVE
          </p>
        </div>
      </div>
    </div>
  );
};
